INSERT INTO INT_SERVERFUNCTION (ID, NAME, DESCRIPTION, TYPE, CODE, JDBC_ID, PUBLIC_EXECUTION, CRON_EXPRESSION, CRON_INPUT_JSON, CREATED_BY) VALUES (119, 'hotPremissaImpostoPorCiclo', 'Premissas de imposto do ciclo.', 'SQL', 'SELECT pi.*, cc.CODIGO, cc.NOME FROM PREMISSA_IMPOSTO pi
     JOIN CONTA_CONTABIL cc ON cc.ID = pi.CONTA_ID WHERE pi.CICLO_ID = {{cicloId}} ORDER BY cc.CODIGO', NULL, FALSE, NULL, NULL, 'sarah@mitralab.io');
